 function publish(e:React.FormEvent){e.preventDefault();if(!title.trim()&&!body.trim()&&!link.trim()&&!asset&&!itemsText.trim()){setNotice("Add content or a resource.");return;}if(link.trim()&&!isHttpUrl(link)){setNotice("Enter a valid http or https link.");return;}const existing=s.posts.find(p=>p.id===editingPostId);const items=itemsText.split(/\n+/).map(text=>text.trim()).filter(Boolean).map((text,index)=>({id:existing?.items?.[index]?.id||"item-"+Date.now()+"-"+index,text,done:existing?.items?.find(item=>item.text===text)?.done||false}));const p:Post={id:editingPostId||"post-"+Date.now(),title:title.trim()||"Channel update",body:body.trim(),link:link.trim(),category:postCategory,asset,at:existing?.at||new Date().toISOString(),status:"published",items,sourceType:postCategory==="Creator / TV / Entertainment"?sourceType:undefined};const posts=editingPostId?s.posts.map(item=>item.id===editingPostId?p:item):[p,...s.posts];save({...s,posts});setTitle("");setBody("");setLink("");setPostCategory(s.category);setAsset(undefined);setItemsText("");setSourceType("Video / stream URL");setEditingPostId("");setNotice(existing?"Published item updated.":"Published to channel.");}
 function editPost(post:Post){setEditingPostId(post.id);setTitle(post.title);setBody(post.body);setLink(post.link);setPostCategory(post.category||s.category);setAsset(post.asset);setItemsText((post.items||[]).map(item=>item.text).join("\n"));setSourceType(post.sourceType||"Video / stream URL");setNotice("Editing "+post.title+". Save to publish your changes.");}
 function removePost(id:string){if(!window.confirm("Delete this published item? This cannot be undone."))return;save({...s,posts:s.posts.filter(post=>post.id!==id)});if(editingPostId===id){setEditingPostId("");setTitle("");setBody("");setLink("");setAsset(undefined);setItemsText("");}setNotice("Published item deleted.");}
 function setPostStatus(id:string,status:"published"|"draft"|"archived"){save({...s,posts:s.posts.map(post=>post.id===id?{...post,status}:post)});setNotice(status==="published"?"Item published to channel.":status==="draft"?"Item unpublished and saved as a draft.":"Item archived.");}
 function togglePostItem(postId:string,itemId:string){save({...s,posts:s.posts.map(post=>post.id===postId?{...post,items:(post.items||[]).map(item=>item.id===itemId?{...item,done:!item.done}:item)}:post)});}
 function addCircle(e:React.FormEvent){e.preventDefault();const list=members.split(/[\n,;]+/).map(x=>personKey(x)).filter(Boolean);if(!circleName.trim())return;const c={id:"circle-"+Date.now(),name:circleName,description:circleDesc,members:list};save({...s,circles:[c,...s.circles]});setCircleName("");setCircleDesc("");setMembers("");setNotice("VIP circle created.");}
 function updateInviteRole(name:string,role:"moderator"|"contributor"|"participant"|"viewer"){save({...s,roles:{...s.roles,[name]:role},people:s.people.map(person=>personKey(person.name)===name?{...person,role}:person)});setNotice(name+" role updated.");}
 function removeInvite(name:string){const remainsInCircle=s.circles.some(circle=>circle.members.includes(name));save({...s,invites:s.invites.filter(item=>item!==name),roles:Object.fromEntries(Object.entries(s.roles||{}).filter(([key])=>key!==name)),people:s.people.map(person=>personKey(person.name)===name?{...person,role:remainsInCircle?(person.role||"participant"):"viewer"}:person)});setNotice(name+" invitation removed.");}
 function addInvite(e:React.FormEvent){e.preventDefault();const personName=invite.trim().replace(/\s+/g," ");if(!personName)return;const key=personKey(personName);if(s.invites.some(item=>personKey(item)===key)) {setNotice("Already invited.");return;}save({...s,invites:[...s.invites,key],roles:{...s.roles,[key]:inviteRole},people:s.people.map(person=>personKey(person.name)===key?{...person,role:inviteRole,invited:true}:person)});setInvite("");setInviteRole("participant");setNotice(personName+" invited as "+inviteRole+".");}
 function send(kind:"comments"|"requests",e:React.FormEvent){e.preventDefault();if(!draft.trim()||!signed)return;const next=[{id:kind+"-"+Date.now(),author:person?.name||name.trim(),text:draft.trim()},...(kind==="comments"?comments:requests)];if(kind==="comments"){setComments(next);localStorage.setItem(KEY+":"+activeWorkspaceId+":comments",JSON.stringify(next));}else{setRequests(next);localStorage.setItem(KEY+":"+activeWorkspaceId+":requests",JSON.stringify(next));}setDraft("");setNotice(kind==="comments"?"Comment posted.":"Request sent to Backpack.");}
